                {locked&&<span style={{marginLeft:"auto",fontSize:11}}>🔒</span>}
                {!locked&&item.badge&&<span style={{marginLeft:"auto",fontSize:9,fontWeight:700,background:`color-mix(in srgb,${b.theme.accent} 20%,transparent)`,color:b.theme.accent,padding:"2px 7px",borderRadius:20}}>{item.badge}</span>}
